//! Miscellaneous Boot Services from UEFI 2.11 §7.5.

use crate::crc32::crc32;
use crate::uefi::status::Status;
use core::{ffi::c_void, ptr, slice};

// The firmware probe bounds each REP string operation to 1024 iterations,
// including compiler-generated byte copies.
pub(crate) const MEMORY_CHUNK: usize = 1024;

/// # Safety
/// A non-null output would hold the count if the platform could supply one.
pub unsafe extern "efiapi" fn get_next_monotonic_count(count: *mut u64) -> Status {
    if count.is_null() {
        Status::INVALID_PARAMETER
    } else {
        // There is no persistent high word at this stage.
        Status::DEVICE_ERROR
    }
}

/// # Safety
/// Nonempty input must cover `length` readable bytes, and a non-null
/// checksum must point to a writable aligned u32.
pub unsafe extern "efiapi" fn calculate_crc32(
    data: *const c_void,
    length: usize,
    checksum: *mut u32,
) -> Status {
    if data.is_null() || checksum.is_null() || length == 0 || length > isize::MAX as usize {
        return Status::INVALID_PARAMETER;
    }
    // SAFETY: the caller supplies this readable span and writable output.
    let value = crc32(unsafe { slice::from_raw_parts(data.cast::<u8>(), length) });
    unsafe { checksum.write(value) };
    Status::SUCCESS
}

/// # Safety
/// For nonempty regions, both buffers must cover `length` bytes. The caller
/// permits reads from the source and writes to the destination. Overlap is valid.
pub unsafe extern "efiapi" fn copy_mem(
    destination: *mut c_void,
    source: *const c_void,
    length: usize,
) {
    let dst = destination.cast::<u8>();
    let src = source.cast::<u8>();
    if length == 0 || ptr::eq(dst, src) {
        return;
    }
    let mut remaining = length;
    let backwards = dst.addr() > src.addr() && dst.addr() - src.addr() < length;
    while remaining != 0 {
        let count = remaining.min(MEMORY_CHUNK);
        let offset = if backwards {
            remaining - count
        } else {
            length - remaining
        };
        // SAFETY: both subranges belong to the caller's spans. The order
        // keeps unprocessed source bytes intact across chunk boundaries.
        unsafe { ptr::copy(src.add(offset), dst.add(offset), count) };
        remaining -= count;
    }
}

/// # Safety
/// For a nonzero length, the buffer must cover `length` writable bytes.
pub unsafe extern "efiapi" fn set_mem(buffer: *mut c_void, length: usize, value: u8) {
    let bytes = buffer.cast::<u8>();
    let mut offset = 0;
    while offset < length {
        let count = (length - offset).min(MEMORY_CHUNK);
        // SAFETY: this chunk is within the caller's writable span.
        unsafe { ptr::write_bytes(bytes.add(offset), value, count) };
        offset += count;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn calculates_crc_and_preserves_output_on_invalid_arguments() {
        let input = b"123456789";
        let mut output = 0;
        let data = input.as_ptr().cast();
        assert_eq!(
            unsafe { calculate_crc32(data, input.len(), &mut output) },
            Status::SUCCESS
        );
        assert_eq!(output, 0xcbf4_3926);
        for (input, length) in [(ptr::null(), 9), (data, 0)] {
            assert_eq!(
                unsafe { calculate_crc32(input, length, &mut output) },
                Status::INVALID_PARAMETER
            );
            assert_eq!(output, 0xcbf4_3926);
        }
        assert_eq!(
            unsafe { calculate_crc32(data, input.len(), ptr::null_mut()) },
            Status::INVALID_PARAMETER
        );
    }

    #[test]
    fn copies_multi_chunk_overlaps_against_the_slice_model() {
        const BYTES: usize = 4 * MEMORY_CHUNK + 13;
        for (src, dst, size) in [
            (1, 17, 3 * MEMORY_CHUNK + 5),
            (17, 1, 3 * MEMORY_CHUNK + 5),
            (0, 3 * MEMORY_CHUNK, MEMORY_CHUNK),
            (1, 1, BYTES - 1),
            (0, BYTES, 0),
        ] {
            let mut actual: [u8; BYTES] = core::array::from_fn(|i| (i % 251) as u8);
            let mut expected = actual;
            expected.copy_within(src..src + size, dst);
            let base = actual.as_mut_ptr();
            unsafe { copy_mem(base.add(dst).cast(), base.add(src).cast(), size) };
            assert_eq!(actual, expected);
        }
    }

    #[test]
    fn sets_only_the_requested_bytes_across_chunks() {
        const LEN: usize = 2 * MEMORY_CHUNK + 5;
        let mut bytes = [0x33u8; LEN + 2];
        unsafe { set_mem(bytes.as_mut_ptr().add(1).cast(), LEN, 0xa5) };
        assert_eq!(bytes[0], 0x33);
        assert_eq!(bytes[1..1 + LEN], [0xa5; LEN]);
        assert_eq!(bytes[LEN + 1], 0x33);
    }
}
